arguments.argument:
if(global.myself.object == -1) exit;

//AFK Check -- double length for server host
if(global.isHost)
    afktimer -= 0.5 * global.delta_factor
else
    afktimer -= 1 * global.delta_factor;

if ((afktimer <= 0) and !global.myself.object.afk)
{
    global.myself.object.afk = true;
    if !instance_exists(TeamSelectController)
        instance_create(0,0,TeamSelectController);
    with(TeamSelectController)
        afk = true;
}

if(global.myself.class == CLASS_ENGINEER || global.myself.object.buildObject[0] != -1)
{
    if((global.myself.sentry || global.myself.dispenser) and !instance_exists(SentryHealthHud))
        instance_create(0,0,SentryHealthHud);

    if(!instance_exists(NutsNBoltsHud))
        instance_create(0,0,NutsNBoltsHud);
}
if(global.myself.class == CLASS_HEAVY || global.myself.object.weaponType[global.myself.object.activeWeapon] == WTYPE_CONSUMABLE)
{
    if(!instance_exists(SandwichHud))
        instance_create(0,0,SandwichHud);
}

// Sticky HUD. Because real men let computers count for them.
else if global.myself.object.weaponType[global.myself.object.activeWeapon] == WTYPE_MINEGUN && !instance_exists(StickyCounter) instance_create(0,0,StickyCounter);

else if global.myself.object.weaponType[global.myself.object.activeWeapon] == WTYPE_HEALBEAM {
    //Uber HUD
    if !instance_exists(UberHud) instance_create(0,0,UberHud);
    //Healing Hud
    if !instance_exists(HealingHud) && global.showHealing = 1 instance_create(0,0,HealingHud);
    //Medic Radar
    if global.medicRadar == 1 && !instance_exists(MedicRadar) instance_create(0,0,MedicRadar);
}

// Health HUD
if  !instance_exists(HealthHud) instance_create(0,0,HealthHud);

// Healed HUD
if !instance_exists(HealedHud) && global.showHealer = 1 instance_create(0,0,HealedHud);

// new huds sorted by addition

//this hud does most of the special displays (cooldown & charge timers)
if !instance_exists(SpecialHud) instance_create(0,0,SpecialHud);

// Frontier Justice HUD
if (global.myself.object.rechargeAbility[global.myself.object.activeWeapon] == ACHARGE_SENTRY_KILLS) && !instance_exists(RevengeCritHud) instance_create(0,0,RevengeCritHud);

//etranger hud
if (global.myself.object.ability[0] == ABILITY_UBERCLOAK || global.myself.object.ability[1] == ABILITY_UBERCLOAK) && !instance_exists(DeadringerHud) instance_create(0,0,DeadringerHud);

//sap crit hud
if (global.myself.object.rechargeAbility[global.myself.object.activeWeapon] == ACHARGE_STAB_KILLS) && !instance_exists(SapCritHud) instance_create(0,0,SapCritHud);

//stab speed hud
//if global.myself.object.ability[0] == STABSPEED > 0 && !instance_exists(StabSpeedHud) instance_create(0,0,StabSpeedHud);
